#!/usr/bin/env node
import { readFileSync } from 'node:fs'
import { formatReport } from './report.js'

/** The counts tally knows, by subcommand. Empty until the first count lands. */
const COUNTS = {}

export function run(argv) {
  const [command, file] = argv
  const count = COUNTS[command]
  if (!count || !file) {
    return { code: 2, out: `usage: tally <${Object.keys(COUNTS).join('|') || 'count'}> <file>` }
  }
  const text = readFileSync(file, 'utf8')
  return { code: 0, out: formatReport([[command, count(text)]]) }
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const { code, out } = run(process.argv.slice(2))
  console.log(out)
  process.exit(code)
}
