/**
 * The subcommands the usage line has to name. A usage test checks for each of them and does not
 * compare the whole line, because other work adds subcommands to it.
 */
const SUBCOMMANDS = ['longest-word']

/** The subcommands a usage line names: the alternatives between its first `<` and `>`. */
function subcommandsNamedIn(usageLine) {
  return /<([^<>]*)>/.exec(usageLine)?.[1].split('|') ?? []
}

/**
 * Asserts that `result` is what `run` returns for wrong arguments: code 2 and the usage line.
 * Each subcommand is looked for as a whole alternative of the line, not as a substring, because
 * one subcommand's name can be contained in another's.
 */
function assertUsage(result) {
  assert.equal(result.code, 2)
  assert.match(result.out, /^usage: tally /)
  const named = subcommandsNamedIn(result.out)
  for (const subcommand of SUBCOMMANDS) {
    assert.ok(named.includes(subcommand), `the usage line names ${subcommand}: ${result.out}`)
  }
}

/** Names that every JavaScript object carries. None of them is a subcommand. */
const NAMES_EVERY_OBJECT_CARRIES = ['toString', 'constructor', '__proto__']

